import{_ as t,o,c as r,a2 as n}from"./chunks/framework.Cdp8-jB6.js";const u=JSON.parse('{"title":"Content-pipeline tooling","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tooling/content-pipelines.md","filePath":"reference/tooling/content-pipelines.md"}'),a={name:"reference/tooling/content-pipelines.md"};function s(d,e,i,c,l,p){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="content-pipeline-tooling" tabindex="-1">Content-pipeline tooling <a class="header-anchor" href="#content-pipeline-tooling" aria-label="Permalink to &quot;Content-pipeline tooling&quot;">​</a></h1><p>Reference for the durable <strong>content</strong> tooling in Orrery — i18n/translation, narrated audio, outbound-link provenance + health, the launches calendar, and the science/data builders. This is a catalogue, not a tutorial: for end-to-end flow see <a href="./../../adr/TA#pipelines">TA.md §pipelines</a> (Pipeline 3 link-provenance, 4 link-health, 8 science-index, 10 i18n, 12 audio), and for operator runbooks the deep references linked per section. Day-to-day rules live in <a href="./../../../AGENTS">AGENTS.md §&quot;i18n rules&quot;</a> and <a href="./../../../AGENTS">AGENTS.md §&quot;Audio narration&quot;</a>.</p><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Command</th><th>When</th></tr></thead><tbody><tr><td>Compile messages</td><td><code>npm run i18n:compile</code></td><td>Prereq of dev/build/check/typecheck/test (auto-chained)</td></tr><tr><td>Translate overlays</td><td><code>scripts/wave23/</code> toolchain</td><td>New base-data → 14-locale overlays (per-wave)</td></tr><tr><td>Translate audio (stub)</td><td><code>npm run audio:translate</code></td><td>Deferred to v0.8 (issue #152) — exits 2</td></tr><tr><td>Generate audio</td><td><code>npm run audio:generate -- --episode &lt;id&gt;</code></td><td>Render one episode&#39;s mp3/vtt/txt</td></tr><tr><td>Full audio rebuild (stub)</td><td><code>npm run audio:build</code></td><td>Deferred to v0.8 — exits 2</td></tr><tr><td>Audio cost gate</td><td><code>npm run audio:check-cost</code></td><td>In preflight; ad-hoc spend check</td></tr><tr><td>Link provenance</td><td><code>npm run build-link-provenance</code></td><td>After editing any <code>links[]</code>/<code>wiki</code> field</td></tr><tr><td>Link health</td><td><code>npm run check-learn-links</code> (<code>--update</code>)</td><td>Periodic outbound-link probe</td></tr><tr><td>Fetch launches</td><td><code>npm run fetch:launches</code></td><td>Rebuild the launches manifest</td></tr><tr><td>Audit launches</td><td><code>npm run audit:launches</code></td><td>Inspect provenance/family gaps after a fetch</td></tr><tr><td>Build science index</td><td><code>npm run build-science-index</code></td><td>Build prereq (auto-chained)</td></tr><tr><td>Precompute porkchops</td><td><code>npm run precompute-porkchops</code></td><td>Build prereq (auto-chained)</td></tr><tr><td>Tech BOM</td><td><code>npm run build-tech-bom</code> / <code>check-tech-bom</code></td><td>Regenerate / CI-verify license BOM</td></tr><tr><td>Site-stories index</td><td><code>tsx scripts/build-site-stories-index.ts</code></td><td>After authoring a new site story</td></tr><tr><td>Colophon original-work</td><td><code>node scripts/build-original-work.mjs</code></td><td>After adding an original diagram</td></tr><tr><td>Cislunar waypoints</td><td><code>tsx scripts/cislunar/generate-*-waypoints.ts</code></td><td>Bake Tier 1.5 trajectory for a mission</td></tr><tr><td>Fleet link repair</td><td><code>tsx scripts/migrate-fleet-linked-*.ts</code></td><td>When <code>validate-data</code> emits the fix-hint</td></tr></tbody></table><hr><h2 id="i18n" tabindex="-1">i18n <a class="header-anchor" href="#i18n" aria-label="Permalink to &quot;i18n&quot;">​</a></h2><h3 id="npm-run-i18n-compile" tabindex="-1"><code>npm run i18n:compile</code> <a class="header-anchor" href="#npm-run-i18n-compile" aria-label="Permalink to &quot;`npm run i18n:compile`&quot;">​</a></h3><p><strong>Command</strong> — <code>paraglide-js compile --project ./project.inlang --outdir ./src/lib/paraglide</code><strong>What</strong> — Compiles the per-locale message catalogues in <code>messages/&lt;locale&gt;.json</code> into the typed <code>src/lib/paraglide/</code> runtime (the <code>t()</code> import surface). 14 locales: <code>ar de en-US es fr hi it ja ko nl pt-BR ru sr-Cyrl zh-CN</code>. <strong>When</strong> — A hard prereq of <code>dev</code>, <code>build</code>, <code>check</code>, <code>check:watch</code>, <code>typecheck</code>, <code>test</code>, <code>test:coverage</code> — every one of those npm targets runs <code>i18n:compile</code> first, so it is rarely invoked by hand. <code>src/lib/paraglide/</code> is generated; don&#39;t hand-edit it. <strong>Gotchas</strong> — Recompiling while <code>vite dev</code> is running can leave HMR holding a stale module graph and surface as a <strong>circular-dependency error</strong> in the browser. It is not a code bug — restart the dev server and it clears (MEMORY: dev-server paraglide-recompile circular dep). <strong>State</strong> — healthy.</p><h3 id="scripts-wave23-translation-toolchain" tabindex="-1"><code>scripts/wave23/</code> translation toolchain <a class="header-anchor" href="#scripts-wave23-translation-toolchain" aria-label="Permalink to &quot;`scripts/wave23/` translation toolchain&quot;">​</a></h3><p><strong>Command</strong> — staged scripts under <code>scripts/wave23/</code> (catalog → maps → apply-translations), run via <code>npx tsx</code>. <strong>What</strong> — The <strong>current recommended</strong> way to translate base-data overlays to all 14 locales, per <a href="./../../adr/TA#pipelines">TA.md §Pipeline 10</a> (ADR-033 + ADR-054). Three stages:</p><ol><li><strong>catalog</strong> — read every en-US overlay (missions, fleet, science, surface sites, ISS/Tiangong modules) into a flat <code>key → en-US string</code> map.</li><li><strong>maps</strong> — translate each string per target locale with <code>argos-translate</code> offline-NMT, merge any LLM spot-fix overrides → per-locale <code>key → translated string</code> map.</li><li><strong>apply-translations</strong> — read each base file, swap en-US fields for the locale&#39;s translation, write the per-locale overlay. The same toolchain is reused identically across mission/fleet/science content — no per-surface forks. <code>scripts/wave23/packed-lines/&lt;locale&gt;/all.txt</code> retains the packed CJK source lines (ja / zh-CN / hi / ko) the stage scripts consume. <strong>When</strong> — After adding base-data IDs and their en-US overlays; translations land in a separate commit from the en-US ship (en-US alone is enough to ship — runtime falls back to en-US). <strong>Gotchas</strong> — <code>sr-Cyrl</code> has no argos model: it is hand-authored, so the pipeline writes a stub overlay for a human curator to fill. Completeness is <strong>gated by <code>npm run validate-data</code></strong> (ADR-069 Layer 1: every declared ID must have an en-US overlay on disk, or preflight/pre-push fails). <strong>State</strong> — healthy. The legacy per-surface <code>scripts/translate-*.mjs</code> passes (Apollo, launchers, panoramas, satellites, science sections, …) were <strong>one-shot per-wave</strong> scripts and are now archived in <a href="./../../../scripts/_archive/i18n/"><code>scripts/_archive/i18n/</code></a> (~35 files). The durable pattern is wave23 + the ADR-069 overlay-completeness gate; don&#39;t write a new per-surface translate script.</li></ol><hr><h2 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h2><p>The narrated-episode pipeline (PRD-016 / RFC-019). v0.7 ships <strong>en-US only</strong>. Source scripts: <code>content/episodes/&lt;locale&gt;/&lt;id&gt;.md</code> (YAML frontmatter + SSML). Outputs: content-addressed <code>static/audio/&lt;locale&gt;/&lt;persona&gt;/&lt;id&gt;.&lt;hash8&gt;.{mp3,vtt,txt}</code>. Manifest: <code>static/data/audio/audio-provenance.json</code>. <strong>Operator runbook:</strong><a href="./../../guides/audio-pipeline-setup">docs/guides/audio-pipeline-setup.md</a>. Adding a provider: see <a href="./../../../AGENTS">AGENTS.md §&quot;Audio narration&quot;</a>.</p><h3 id="npm-run-audio-generate" tabindex="-1"><code>npm run audio:generate</code> <a class="header-anchor" href="#npm-run-audio-generate" aria-label="Permalink to &quot;`npm run audio:generate`&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run audio:generate -- --episode &lt;id&gt; [--locale en-US] [--provider google|elevenlabs]</code> (<code>scripts/audio/generate.ts</code>) <strong>What</strong> — Pipeline 2 — the operational entry point in v0.7. Reads the episode markdown, renders SSML via the selected <code>TtsProvider</code>, writes the <code>.mp3</code>/<code>.vtt</code>/<code>.txt</code> triple, appends a cost-ledger row, and records an <code>audio-provenance.json</code> entry (text authorship + provider + tts_model + voice id, all surfaced on <code>/credits</code>). <strong>When</strong> — Operator-only, per episode. Provider precedence: CLI <code>--provider</code> → <code>TTS_PROVIDER</code> env → default <code>google</code>. <strong>Gotchas</strong> — Cache key is <code>SHA-256(provider + voiceId + ssml)</code>; identical input never re-generates (reuses the existing <code>.&lt;hash8&gt;.mp3</code>, logs a <code>cached</code> ledger row). Editing SSML forces a full re-render. Adding/renaming an episode without a provenance row leaves it invisible at runtime. <strong>State</strong> — healthy.</p><h3 id="npm-run-audio-check-cost" tabindex="-1"><code>npm run audio:check-cost</code> <a class="header-anchor" href="#npm-run-audio-check-cost" aria-label="Permalink to &quot;`npm run audio:check-cost`&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run audio:check-cost</code> (<code>scripts/audio/check-cost-thresholds.ts</code>) <strong>What</strong> — Reads <code>static/data/audio/cost-ledger.json</code>, prints the current month&#39;s per-provider totals, and gates on spend: <strong>$50/mo soft warn</strong> (prints, exit 0), <strong>$200/mo hard halt</strong> (prints, exit 1). <strong>When</strong> — Wired into <code>npm run preflight</code> (and <code>preflight:full</code>) — an over-cap month blocks pushes. <strong>Gotchas</strong> — No ledger → no-op (exit 0). The ledger is the gate&#39;s only input; nothing else clamps spend. <strong>State</strong> — healthy.</p><h3 id="npm-run-audio-translate-npm-run-audio-build-stubs" tabindex="-1"><code>npm run audio:translate</code> / <code>npm run audio:build</code> (stubs) <a class="header-anchor" href="#npm-run-audio-translate-npm-run-audio-build-stubs" aria-label="Permalink to &quot;`npm run audio:translate` / `npm run audio:build` (stubs)&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run audio:translate</code> (<code>translate.ts</code>) | <code>npm run audio:build</code> (<code>build.ts</code>) <strong>What</strong> — <code>audio:translate</code> = Pipeline 1, Claude-API SSML-safe en-US→11-locale translation; <code>audio:build</code> = full-corpus translate→generate orchestrator. Both are <strong>not-implemented stubs</strong>. <strong>When</strong> — Deferred to v0.8 (epic #146 / issue #152). For v0.7 en-US, chain <code>audio:generate</code> per episode. <strong>Gotchas</strong> — Both exit <strong>2</strong> (operator-misuse), not 1, so an accidental <code>&amp;&amp;</code> chain doesn&#39;t fail-stop. <strong>State</strong> — stubbed pending v0.8.</p><h3 id="audio-support-modules-scripts-audio" tabindex="-1">Audio support modules (<code>scripts/audio/</code>) <a class="header-anchor" href="#audio-support-modules-scripts-audio" aria-label="Permalink to &quot;Audio support modules (`scripts/audio/`)&quot;">​</a></h3><p>Not directly runnable — imported by the pipeline above:</p><ul><li><strong><code>cost-ledger.ts</code></strong> — <code>appendEntry</code> / threshold guard. Atomic tmp-file+rename writes; UTC-ISO <code>ts</code> asserted (catches month-boundary drift); incremental per-month totals.</li><li><strong><code>provenance.ts</code></strong> — <code>audio-provenance.json</code> append helper, mirrors the image-provenance pattern.</li><li><strong><code>tts/provider.ts</code></strong> — <code>TtsProvider</code> interface + <code>Persona</code>/<code>ProviderName</code> unions.</li><li><strong><code>tts/google.ts</code>, <code>tts/elevenlabs.ts</code></strong> — concrete providers (Google Cloud TTS, ElevenLabs).</li><li><strong><code>tts/retry.ts</code></strong> — <code>withRetry</code>: 3-attempt exponential backoff on network/5xx/429, honours <code>Retry-After</code>.</li><li><strong><code>suggest-stages.ts</code></strong> — <code>tsx scripts/audio/suggest-stages.ts &lt;episode-id&gt;</code>: parses an episode&#39;s SSML + VTT and emits a VTT-anchored <code>EPISODE_STAGES</code> block to paste into <code>src/lib/audio-tour.ts</code>.</li></ul><hr><h2 id="links-launches" tabindex="-1">Links &amp; launches <a class="header-anchor" href="#links-launches" aria-label="Permalink to &quot;Links &amp; launches&quot;">​</a></h2><h3 id="npm-run-build-link-provenance" tabindex="-1"><code>npm run build-link-provenance</code> <a class="header-anchor" href="#npm-run-build-link-provenance" aria-label="Permalink to &quot;`npm run build-link-provenance`&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run build-link-provenance</code> (<code>scripts/build-link-provenance.ts</code>) <strong>What</strong> — ADR-051 Milestone L-B. Walks every JSON under <code>static/data/</code> (+ <code>i18n/en-US/</code> overlays), collects <code>links: [{l,u,t}]</code> arrays + the small-body <code>wiki</code> field, classifies each URL by host + tier, and writes <code>static/data/link-provenance.json</code> + <code>docs/provenance/last-link-provenance-diff.md</code>. The manifest is the single source consumed by validate-data, the runtime data layer, <code>LinkCredit</code>, and <code>/library</code>. <strong>When</strong> — After adding/editing any outbound link. Chained into <code>npm run fetch</code>. <strong>Gotchas</strong> — <strong>Fails closed</strong> when a URL can&#39;t be classified to a known <code>source_id</code> in <code>static/data/source-logos.json</code> — register the host first. <strong>State</strong> — healthy.</p><h3 id="npm-run-check-learn-links" tabindex="-1"><code>npm run check-learn-links</code> <a class="header-anchor" href="#npm-run-check-learn-links" aria-label="Permalink to &quot;`npm run check-learn-links`&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run check-learn-links</code> (<code>--update</code>) (<code>scripts/check-learn-links.ts</code>) <strong>What</strong> — ADR-051 Milestone L-E. Probes every <code>link-provenance.json</code> entry (HEAD, GET fallback for HEAD-blocking hosts), records alive/redirect/dead, writes <code>docs/provenance/last-link-check.md</code>. With <strong><code>--update</code></strong> it rewrites <code>last_verified</code> (YYYY-MM-DD) on every ≤400 entry and re-emits the manifest. <strong>When</strong> — Periodic health sweep; <code>fetch</code> runs it with <code>--update</code>. <strong>Gotchas</strong> — Network-bound (slow); <code>--update</code> mutates the manifest, so run after <code>build-link-provenance</code>. <strong>State</strong> — healthy.</p><h3 id="npm-run-fetch-launches" tabindex="-1"><code>npm run fetch:launches</code> <a class="header-anchor" href="#npm-run-fetch-launches" aria-label="Permalink to &quot;`npm run fetch:launches`&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run fetch:launches</code> (<code>scripts/fetch-launches.ts</code>) <strong>What</strong> — PRD-020 / RFC-023 launches-calendar orchestrator. Pulls each registered <code>LaunchSource</code> (GCAT historic primary, LL2 upcoming fallback, plus NASA/SpaceX/ESA agency-direct) in priority order, dedupes by stable Orrery id, merges first-seen-wins, applies the curation override file, writes the manifest files + an audit-report stub. <strong>When</strong> — Rebuilding the launches manifest. Docker variant: <code>npm run docker:fetch-launches</code>. <strong>Gotchas</strong> — GCAT release is pinned (<code>GCAT_RELEASE_PIN</code>) for reproducibility. <strong>State</strong> — healthy.</p><h3 id="npm-run-audit-launches" tabindex="-1"><code>npm run audit:launches</code> <a class="header-anchor" href="#npm-run-audit-launches" aria-label="Permalink to &quot;`npm run audit:launches`&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run audit:launches</code> (<code>scripts/audit-report-launches.ts</code>) <strong>What</strong> — RFC-023 §10. Generates the gitignored dev-only <code>static/audit-report-launches.html</code>: provenance gaps (rows where the agency-direct chain returned nothing, fell back to LL2), unmapped rocket families, and tier-reason distribution. <strong>When</strong> — After <code>fetch:launches</code>, to triage which agency-direct provider to improve next. <strong>State</strong> — healthy.</p><h3 id="scripts-gcat-parse-launch-log-ts" tabindex="-1"><code>scripts/gcat/parse-launch-log.ts</code> <a class="header-anchor" href="#scripts-gcat-parse-launch-log-ts" aria-label="Permalink to &quot;`scripts/gcat/parse-launch-log.ts`&quot;">​</a></h3><p><strong>Command</strong> — library (imported by <code>GcatSource</code>); covered by <code>parse-launch-log.test.ts</code>. <strong>What</strong> — RFC-023 §12.1. Pure-function parser for Jonathan McDowell&#39;s GCAT <code>launch.tsv</code> master launch list (28-field, space-padded, comment-prefixed header). Asserts the header, parses dates with precision, builds stable ids. <strong>Gotchas</strong> — GCAT is CC-BY J.C. McDowell — preserve attribution. Header-shape changes upstream trip <code>assertGcatHeader</code>. <strong>State</strong> — healthy.</p><hr><h2 id="science-data-builders" tabindex="-1">Science &amp; data builders <a class="header-anchor" href="#science-data-builders" aria-label="Permalink to &quot;Science &amp; data builders&quot;">​</a></h2><h3 id="npm-run-build-science-index" tabindex="-1"><code>npm run build-science-index</code> <a class="header-anchor" href="#npm-run-build-science-index" aria-label="Permalink to &quot;`npm run build-science-index`&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run build-science-index</code> (<code>scripts/build-science-index.ts</code>) <strong>What</strong> — RFC-011 step 9. Walks every section overlay in <code>i18n-src/en-US/science/</code> → <code>static/data/science-index.json</code> (one entry per section: URL + title + intro + key terms) for the <code>⌘K</code> fuzzy search in <code>ScienceSearch.svelte</code>. <strong>When</strong> — <strong>Build prereq</strong> (auto-chained into <code>npm run build</code>). <strong>State</strong> — healthy.</p><h3 id="npm-run-precompute-porkchops" tabindex="-1"><code>npm run precompute-porkchops</code> <a class="header-anchor" href="#npm-run-precompute-porkchops" aria-label="Permalink to &quot;`npm run precompute-porkchops`&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run precompute-porkchops</code> (<code>scripts/precompute-porkchops.ts</code>) <strong>What</strong> — ADR-016/026/028. Pre-computes Lambert porkchop grids for 9 destinations (Mercury → Pluto, Ceres) → <code>static/data/porkchop/earth-to-&lt;id&gt;.json</code>, so <code>/plan</code> first paint never spawns a worker. <strong>When</strong> — <strong>Build prereq</strong> (auto-chained into <code>npm run build</code>). <strong>Gotchas</strong> — Idempotent — the Lambert solver is deterministic and output is rounded before serialising, so re-runs produce identical bytes. Grids are committed for offline capability. <strong>State</strong> — healthy.</p><h3 id="npm-run-build-tech-bom-check-tech-bom" tabindex="-1"><code>npm run build-tech-bom</code> / <code>check-tech-bom</code> <a class="header-anchor" href="#npm-run-build-tech-bom-check-tech-bom" aria-label="Permalink to &quot;`npm run build-tech-bom` / `check-tech-bom`&quot;">​</a></h3><p><strong>Command</strong> — <code>npm run build-tech-bom</code> | <code>npm run check-tech-bom</code> (<code>scripts/build-tech-bom.ts [--check]</code>) <strong>What</strong> — Walks the npm dep tree (<code>npm ls --json --all --omit=optional</code>), reads each package&#39;s license, classifies runtime vs development, emits <code>docs/TECH-BOM.md</code> + <code>static/data/tech-bom.json</code> (CycloneDX-ish). <code>--check</code> verifies the committed output is current without rewriting. <strong>When</strong> — After dependency changes; <code>check-tech-bom</code> for a CI drift gate. <strong>State</strong> — healthy.</p><h3 id="scripts-build-site-stories-index-ts" tabindex="-1"><code>scripts/build-site-stories-index.ts</code> <a class="header-anchor" href="#scripts-build-site-stories-index-ts" aria-label="Permalink to &quot;`scripts/build-site-stories-index.ts`&quot;">​</a></h3><p><strong>Command</strong> — <code>tsx scripts/build-site-stories-index.ts</code><strong>What</strong> — Builds <code>static/data/site-stories/index.json</code> from the <code>site-stories/</code> file listing so <code>getSiteStory</code> can probe before fetching — launch sites without an editorial story no longer trigger speculative 404s. <strong>When</strong> — After authoring a new site story. <strong>Gotchas</strong> — Idempotent (rewrites only on id-list change) — safe to chain into preflight as a no-op. <strong>State</strong> — healthy. Not npm-aliased.</p><h3 id="scripts-build-original-work-mjs" tabindex="-1"><code>scripts/build-original-work.mjs</code> <a class="header-anchor" href="#scripts-build-original-work-mjs" aria-label="Permalink to &quot;`scripts/build-original-work.mjs`&quot;">​</a></h3><p><strong>Command</strong> — <code>node scripts/build-original-work.mjs</code><strong>What</strong> — Generates <code>static/data/original-work.json</code>, the bill-of-materials of Orrery&#39;s <strong>original</strong> content for <code>/colophon</code> (also consumed by <code>/science</code>). Auto-scans the hand-authored SVG diagram directories; 3D/canvas/UI/writing categories are curated inline (live-rendered geometry has no thumbnail, so those link to the drawing route). <strong>When</strong> — After adding an original diagram. <strong>Standing tool</strong> (not archived). <strong>State</strong> — healthy.</p><h3 id="scripts-cislunar" tabindex="-1"><code>scripts/cislunar/</code> <a class="header-anchor" href="#scripts-cislunar" aria-label="Permalink to &quot;`scripts/cislunar/`&quot;">​</a></h3><ul><li><strong><code>generate-hybrid-waypoints.ts</code></strong> — <code>tsx scripts/cislunar/generate-hybrid-waypoints.ts &lt;mission.json&gt;</code>. GH #107. Reads a Moon mission&#39;s parametric Tier-1 <code>flight.cislunar_profile</code> + event METs, runs the same <code>buildCislunarTrajectory</code> the renderer uses, resamples to 100 MET-even waypoints, pins event anchors, writes back the Tier-1.5 waypoints.</li><li><strong><code>generate-helio-hybrid-waypoints.ts</code></strong> — <code>#107 Step 6d</code>. The interplanetary mirror for Mars/outer-system missions (<code>buildInterplanetaryTrajectory</code> → <code>flight.interplanetary_profile.waypoints_helio_au</code>).</li><li><strong><code>check-science-map-refs.ts</code></strong> — validates every <code>(tab, slug)</code> in <code>cislunar-phase-science-map.json</code> resolves to a real <code>/science</code> section file; <strong>chained from <code>validate-data</code></strong> so a typo fails fast instead of producing a dead <code>?</code> chip in <code>/fly</code>.</li></ul><p><strong>State</strong> — healthy. The two generators are per-mission CLI tools, run when adding/updating a Tier-1.5 trajectory.</p><h3 id="fleet-link-repair-tools-—-migrate-fleet-linked-missions-sites-ts" tabindex="-1">Fleet link-repair tools — <code>migrate-fleet-linked-{missions,sites}.ts</code> <a class="header-anchor" href="#fleet-link-repair-tools-—-migrate-fleet-linked-missions-sites-ts" aria-label="Permalink to &quot;Fleet link-repair tools — `migrate-fleet-linked-{missions,sites}.ts`&quot;">​</a></h3><p><strong>Command</strong> — <code>tsx scripts/migrate-fleet-linked-missions.ts</code> | <code>tsx scripts/migrate-fleet-linked-sites.ts</code><strong>What</strong> — Derive the reverse <code>linked_missions</code> / <code>linked_sites</code> pointers on fleet entries mechanically from the forward <code>fleet_refs</code> on missions / moon-sites / mars-sites / earth-objects, keeping the bidirectional graph (ADR-052) consistent. <strong>When</strong> — <strong>Run when <code>validate-data</code> tells you to.</strong> The symmetric-link validator emits these exact commands as live fix-hints when <code>fleet_refs</code> ↔ <code>linked_*</code> drift (<code>scripts/validate-data.ts</code> lines 572 / 626). <strong>Gotchas</strong> — Originally one-shot migrations, deliberately <strong>kept</strong> (not archived) because they double as standing repair tools — don&#39;t move them to <code>_archive/</code>. <strong>State</strong> — healthy (as repair tools).</p><hr><p><em>See also: <a href="./README">README.md</a> (tooling index) · <a href="./data-validation">data-validation.md</a> · <a href="./image-pipeline">image-pipeline.md</a> · <a href="./../../adr/ADR-051">ADR-051</a> · <a href="./../../adr/ADR-069">ADR-069</a> · <a href="./../../adr/TA#pipelines">TA.md §pipelines</a>.</em></p>',54)])])}const g=t(a,[["render",s]]);export{u as __pageData,g as default};
